arguments.new_str:
using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // In .NET 9, ZipArchiveEntry now sets the UTF-8 flag by default for non-ASCII names.
        // Our legacy Java consumer expects Shift-JIS encoding, so we must specify the encoding
        // explicitly to prevent the UTF-8 flag from being set.
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, Encoding.GetEncoding("shift_jis"));
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

